CREATE VIEW `view_riyousha_alive` (`email`,`user_role`,`riyousha_id`,`riyousha_code`,`all_name`,`search_text`) AS with `role_partner` as (select `user_role`.`email` AS `email`,`user_role`.`role` AS `role`,`user_role`.`riyousha_code` AS `riyousha_code` from `user_role` where ((`user_role`.`is_latest` = 1) and (`user_role`.`riyousha_code` <> 0) and (`user_role`.`role` = 'partner_api'))), `role_manager` as (select `user_role`.`email` AS `email`,`user_role`.`role` AS `role`,`user_role`.`riyousha_code` AS `riyousha_code` from `user_role` where ((`user_role`.`is_latest` = 1) and (`user_role`.`riyousha_code` <> 0) and (`user_role`.`role` = 'manager'))) select `role_partner`.`email` AS `email`,`role_partner`.`role` AS `user_role`,`partner`.`riyousha_partner_api_master_id` AS `ruiyousha_id`,`role_partner`.`riyousha_code` AS `riyousha_code`,`partner`.`all_name` AS `all_name`,`partner`.`search_text` AS `search_text` from (`riyousha_partner_api_master` `partner` join `role_partner` on((`role_partner`.`riyousha_code` = `partner`.`riyousha_partner_api_master_code`))) where (`partner`.`is_latest` = 1) union select `role_manager`.`email` AS `email`,`role_manager`.`role` AS `user_role`,`manager`.`riyousha_manager_master_id` AS `ruiyousha_id`,`role_manager`.`riyousha_code` AS `riyousha_code`,`manager`.`all_name` AS `all_name`,`manager`.`search_text` AS `search_text` from (`riyousha_manager_master` `manager` join `role_manager` on((`role_manager`.`riyousha_code` = `manager`.`riyousha_manager_master_code`))) where (`manager`.`is_latest` = 1);
